 void SyncMonitorWidthControls(MonitorOptions settings){
  if(liveWidth==null)return;
  if(liveWidthInfo!=null&&liveSnapshot!=null&&liveSnapshot.TaskbarWidth>0)liveWidthInfo.Text=T("Current width: ","当前宽度：")+liveSnapshot.TaskbarWidth+T(" · Minimum readable width: "," · 最小可读宽度：")+liveSnapshot.TaskbarMinWidth;
  if(pendingLiveWidth>0||liveWidthText.IsKeyboardFocusWithin)return;
  int minimum=liveSnapshot!=null&&liveSnapshot.TaskbarMinWidth>0?Math.Max(140,Math.Min(1200,liveSnapshot.TaskbarMinWidth)):140;
  liveAutoWidth.IsChecked=settings.TaskbarWidth==0;liveWidth.IsEnabled=liveWidthText.IsEnabled=true;liveWidth.Minimum=minimum;
  int value=settings.TaskbarWidth>0?settings.TaskbarWidth:liveSnapshot!=null&&liveSnapshot.TaskbarWidth>0?liveSnapshot.TaskbarWidth:360;liveWidth.Value=Math.Max(minimum,Math.Min(1200,value));liveWidthText.Text=((int)liveWidth.Value).ToString();
 }
