  var settingsRow=new WrapPanel{Margin=new Thickness(0,2,0,12)};var adapters=new List<AdapterOption>{new AdapterOption{Id="auto",Text=T("Automatic · physical adapter","自动 · 物理联网网卡")}};if(liveSnapshot!=null)adapters.AddRange(liveSnapshot.Adapters.Select(a=>new AdapterOption{Id=a.Id,Text=a.Name+(a.Connected?"":" · "+T("Standby","待连接"))}));if(!adapters.Any(a=>a.Id==options.Adapter))adapters.Add(new AdapterOption{Id=options.Adapter,Text=options.Adapter});
