  var intervalBox=new StackPanel();intervalBox.Children.Add(Txt(T("Refresh interval","刷新间隔"),12));liveInterval=new ComboBox{ItemsSource=new[]{"0.5 s","1 s","2 s"},SelectedIndex=options.Interval==500?0:options.Interval==2000?2:1,MinWidth=130};liveInterval.SelectionChanged+=(s,e)=>{if(!liveChanging)ChangeMonitor(o=>o.Interval=new[]{500,1000,2000}[liveInterval.SelectedIndex]);};intervalBox.Children.Add(liveInterval);intervalBox.Margin=new Thickness(0,0,16,0);settingsRow.Children.Add(intervalBox);var periodBox=new StackPanel();periodBox.Children.Add(Txt(T("Traffic period","流量累计周期"),12));livePeriod=new ComboBox{ItemsSource=Enumerable.Range(0,5).Select(i=>MonitorOptions.PeriodLabel(i,zh)).ToArray(),SelectedIndex=options.TrafficPeriod,MinWidth=150};livePeriod.SelectionChanged+=(s,e)=>{if(!liveChanging)ChangeMonitor(o=>o.TrafficPeriod=livePeriod.SelectedIndex);};periodBox.Children.Add(livePeriod);settingsRow.Children.Add(periodBox);periodBox.Margin=new Thickness(0,0,16,0);var precisionBox=new StackPanel();precisionBox.Children.Add(Txt(T("CPU / memory precision","CPU／内存精度"),12));livePrecision=new ComboBox{ItemsSource=zh?new[]{"整数（12%）","一位小数（12.3%）"}:new[]{"Integer (12%)","1 decimal place (12.3%)"},SelectedIndex=options.PerformanceDigits,MinWidth=190};livePrecision.SelectionChanged+=(s,e)=>{if(!liveChanging&&livePrecision.SelectedIndex>=0)ChangeMonitor(o=>o.PerformanceDigits=livePrecision.SelectedIndex);};precisionBox.Children.Add(livePrecision);settingsRow.Children.Add(precisionBox);page.Children.Add(settingsRow);AddMonitorWidthControls(options);AddMonitorColorControls(options);
