 void RefreshLiveMonitor(){
  if(WindowState==WindowState.Minimized||tabs.SelectedIndex!=5)return;
  try{var next=monitorChannel.Read();if(next!=null)liveSnapshot=next;var settings=MonitorOptions.Load(Store.Root);
   liveChanging=true;try{if(liveEnabled!=null){liveEnabled.IsChecked=settings.Enabled;liveTaskbar.IsChecked=settings.OnTaskbar;bool[] values={settings.Download,settings.Upload,settings.Cpu,settings.Memory,settings.DailyTraffic};for(int i=0;i<liveItems.Count;i++)liveItems[i].IsChecked=values[i];if(liveInterval!=null)liveInterval.SelectedIndex=settings.Interval==500?0:settings.Interval==2000?2:1;if(livePeriod!=null)livePeriod.SelectedIndex=settings.TrafficPeriod;if(livePrecision!=null)livePrecision.SelectedIndex=settings.PerformanceDigits;SyncMonitorWidthControls(settings);SyncMonitorColorControls(settings);}}finally{liveChanging=false;}
   if(liveTrafficTitles.Count>0){liveTrafficTitles["todayDown"].Text=MonitorOptions.TrafficTitle(settings.TrafficPeriod,zh,false);liveTrafficTitles["todayUp"].Text=MonitorOptions.TrafficTitle(settings.TrafficPeriod,zh,true);}if(liveStatus==null)return;
   if(!settings.Enabled){foreach(var value in liveValues.Values)value.Text="—";liveStatus.Text=T("Enable real-time monitoring to start sampling.","勾选“启用实时监控”即可开始采样。");return;}
   if(liveSnapshot==null||DateTime.Now-DateTime.Parse(liveSnapshot.At)>TimeSpan.FromSeconds(6)){foreach(var value in liveValues.Values)value.Text="—";liveStatus.Text=T("Connecting to live monitor…","正在连接实时监控组件…");return;}
   liveValues["download"].Text=MonitorMetrics.Speed(liveSnapshot.Download);liveValues["upload"].Text=MonitorMetrics.Speed(liveSnapshot.Upload);liveValues["cpu"].Text=settings.PerformanceText(liveSnapshot.Cpu);liveValues["memory"].Text=settings.PerformanceText(liveSnapshot.MemoryPercent);liveValues["memory"].ToolTip=MonitorMetrics.Bytes(liveSnapshot.MemoryUsed)+" / "+MonitorMetrics.Bytes(liveSnapshot.MemoryTotal);bool periodReady=settings.TrafficPeriod==liveSnapshot.TrafficPeriod;liveValues["todayDown"].Text=periodReady?MonitorMetrics.Bytes(settings.TrafficPeriod==0?liveSnapshot.TodayDownload:liveSnapshot.TrafficDownload):"—";liveValues["todayUp"].Text=periodReady?MonitorMetrics.Bytes(settings.TrafficPeriod==0?liveSnapshot.TodayUpload:liveSnapshot.TrafficUpload):"—";
   string state=!settings.OnTaskbar?T("Taskbar display: ready to enable","任务栏显示：勾选即可开启"):liveSnapshot.Attached?T("Taskbar display: active","任务栏显示：已开启"):liveSnapshot.TaskbarStatus=="select-items"?T("Select taskbar items above","请勾选上方的任务栏显示项目"):liveSnapshot.TaskbarStatus=="layout"?T("Taskbar display: adjust the horizontal layout or select fewer items","任务栏显示：调整水平任务栏空间或勾选较少项目即可显示"):T("Taskbar display: connecting","任务栏显示：正在连接");liveStatus.ToolTip=liveSnapshot.Error;liveStatus.Text=(String.IsNullOrEmpty(liveSnapshot.Adapter)?T("Connecting to a physical adapter","正在连接物理网卡"):liveSnapshot.Adapter)+" · "+settings.Interval+" ms · "+DateTime.Parse(liveSnapshot.At).ToString("HH:mm:ss")+"\n"+state;
   if(liveAdapter!=null&&!liveAdapter.IsDropDownOpen){var available=((IEnumerable<AdapterOption>)liveAdapter.ItemsSource).ToList();var desired=new List<AdapterOption>{new AdapterOption{Id="auto",Text=T("Automatic · physical adapter","自动 · 物理联网网卡")}};desired.AddRange(liveSnapshot.Adapters.Select(a=>new AdapterOption{Id=a.Id,Text=a.Name}));if(!desired.Any(a=>a.Id==settings.Adapter))desired.Add(new AdapterOption{Id=settings.Adapter,Text=settings.Adapter});liveChanging=true;try{if(!available.Select(a=>a.Id).SequenceEqual(desired.Select(a=>a.Id))){liveAdapter.ItemsSource=desired;available=desired;}int index=Math.Max(0,available.FindIndex(a=>a.Id==settings.Adapter));if(liveAdapter.SelectedIndex!=index)liveAdapter.SelectedIndex=index;}finally{liveChanging=false;}}
  }catch(Exception ex){if(liveStatus!=null)liveStatus.Text=T("Live monitor status: ","实时监控状态：")+ex.Message;}
 }
